import { BADGE_3D_CONFIG } from './Badge3DConfig.js';

export const BADGE_SETTINGS_KEY = 'spark-award:badge3d:v1';
export const MATERIAL_ROLES = ['body','edge','star','starEdge','starHighlight','inset','rim','letters','reverse','reverseLetters'];
const numeric = (value, fallback, min, max) => typeof value === 'number' && Number.isFinite(value) ? Math.min(max,Math.max(min,value)) : fallback;
export function normalizeBadgeParameters(input = {}) {
  if(!input || typeof input!=='object') input={};
  const result={version:1,thickness:numeric(input.thickness,.074,.025,.5),bevel:numeric(input.bevel,1,0,2),relief:numeric(input.relief,1,.25,3),materials:{}};
  for(const role of MATERIAL_ROLES) {
    const value=input.materials?.[role];
    if(!value || typeof value!=='object')continue;
    const material={};
    for(const key of ['metalness','roughness']) if(typeof value[key]==='number'&&Number.isFinite(value[key])) material[key]=numeric(value[key],.5,0,1);
    if(Object.keys(material).length)result.materials[role]=material;
  }
  return result;
}
export function defaultBadgeParameters() { return normalizeBadgeParameters(BADGE_3D_CONFIG); }
export function readAppliedBadgeParameters(storage) {
  try {
    const saved=JSON.parse((storage ?? globalThis.localStorage)?.getItem(BADGE_SETTINGS_KEY) ?? 'null');
    if(saved?.version===1)return normalizeBadgeParameters(saved);
  } catch { /* Unavailable storage or invalid JSON: use project defaults. */ }
  return defaultBadgeParameters();
}
export function saveBadgeParameters(parameters, storage=globalThis.localStorage) {
  const normalized=normalizeBadgeParameters(parameters);
  storage.setItem(BADGE_SETTINGS_KEY,JSON.stringify(normalized));
  return normalized;
}
export function exportBadgeConfiguration(parameters) {
  return '// Generated by badge-lab.html. Shared by the lab and unlock page.\nexport const BADGE_3D_CONFIG = '+JSON.stringify(normalizeBadgeParameters(parameters),null,2)+';\n';
}
